command:
$fqbn = Read-Host "Voor welk board wil je compileren? (uno / nano / mega / micro)";
if (-not $fqbn) { $fqbn = "arduino:avr:uno" };
if ($fqbn -eq 'uno') { $fqbn = 'arduino:avr:uno' };
if ($fqbn -eq 'nano') { $fqbn = 'arduino:avr:nano' };
if ($fqbn -eq 'mega') { $fqbn = 'arduino:megaavr:nanoevery' };
if ($fqbn -eq 'micro') { $fqbn = 'arduino:avr:micro' };
Write-Host "Compileer voor: $fqbn" -ForegroundColor Cyan;
arduino-cli compile --fqbn $fqbn "${ZED_DIRNAME}"

$boards = arduino-cli board list --json | ConvertFrom-Json;
$auto = $boards | Where-Object { $_.port.protocol -eq 'serial' } | Select-Object -First 1;
if ($auto) {
  $port = $auto.port.address;
  if ($auto.matching_boards -and $auto.matching_boards.Count -gt 0) {
    $fqbn = $auto.matching_boards[0].fqbn;
    Write-Host "Auto-detect succesvol: $fqbn" -ForegroundColor Green;
  } else {
    Write-Host "Onbekend board (kloon). Typ: uno, nano, mega of micro" -ForegroundColor Yellow;
    $input = Read-Host "Geef board type";
    $fqbn = $input;
    if ($input -eq 'uno') { $fqbn = 'arduino:avr:uno' };
    if ($input -eq 'nano') { $fqbn = 'arduino:avr:nano' };
    if ($input -eq 'mega') { $fqbn = 'arduino:megaavr:nanoevery' };
    if ($input -eq 'micro') { $fqbn = 'arduino:avr:micro' };
  }
  Write-Host "Uploaden naar: $fqbn op poort $port..." -ForegroundColor Cyan;
  arduino-cli upload --fqbn $fqbn --port $port "${ZED_DIRNAME}";
} else {
  Write-Host "FOUT: Geen USB-poort gevonden! Sluit je board aan." -ForegroundColor Red;
}

$boards = arduino-cli board list --json | ConvertFrom-Json;
$auto = $boards | Where-Object { $_.port.protocol -eq 'serial' } | Select-Object -First 1;
if ($auto) {
  $port = $auto.port.address;
  if ($auto.matching_boards -and $auto.matching_boards.Count -gt 0) {
    $fqbn = $auto.matching_boards[0].fqbn;
    Write-Host "Auto-detect succesvol: $fqbn" -ForegroundColor Green;
  } else {
    Write-Host "Onbekend board (kloon). Typ: uno, nano, mega of micro" -ForegroundColor Yellow;
    $input = Read-Host "Geef board type";
    $fqbn = $input;
    if ($input -eq 'uno') { $fqbn = 'arduino:avr:uno' };
    if ($input -eq 'nano') { $fqbn = 'arduino:avr:nano' };
    if ($input -eq 'mega') { $fqbn = 'arduino:megaavr:nanoevery' };
    if ($input -eq 'micro') { $fqbn = 'arduino:avr:micro' };
  }
  Write-Host "Compileren + uploaden naar: $fqbn op poort $port..." -ForegroundColor Cyan;
  arduino-cli compile --fqbn $fqbn --upload --port $port "${ZED_DIRNAME}";
} else {
  Write-Host "FOUT: Geen USB-poort gevonden! Sluit je board aan." -ForegroundColor Red;
}

$boards = arduino-cli board list --json | ConvertFrom-Json;
$auto = $boards | Where-Object { $_.port.protocol -eq 'serial' } | Select-Object -First 1;
if ($auto) {
  $port = $auto.port.address;
  Write-Host "Seriële monitor start op poort: $port" -ForegroundColor Cyan;
  arduino-cli monitor --port $port --config "baudrate=115200";
} else {
  Write-Host "FOUT: Geen actieve USB-poort gevonden." -ForegroundColor Red;
}

$lib = Read-Host "Welke library wil je installeren?";
if ($lib) { Write-Host "Library $lib installeren..." -ForegroundColor Cyan;
arduino-cli lib install "$lib" }

$file = Get-ChildItem "${ZED_DIRNAME}" -Filter "*.ino" | Select-Object -First 1;
if ($file) {
  $includes = Get-Content $file.FullName | ForEach-Object { if ($_ -match '#include\s+[<\"]([^>\"]+)[>\"]') { $Matches[1] } };
  $includes | Where-Object { $_ } | ForEach-Object {
    $cleanLib = $_.Replace('.h', '').Replace('_', ' ');
    if ($cleanLib -eq 'DHT') { $cleanLib = 'DHT sensor library' };
    if ($cleanLib -notmatch 'Arduino|SPI|Wire|SoftwareSerial|EEPROM') {
      Write-Host "Systeem probeert te installeren: $cleanLib" -ForegroundColor Cyan;
      arduino-cli lib install "$cleanLib";
    }
  }
} else {
  Write-Host "FOUT: Geen .ino bestand gevonden." -ForegroundColor Red;
}
